#!/usr/bin/env bash
set -euo pipefail

: "${ALMAGEST_E2E_TIMEOUT:=120}"
# shellcheck disable=SC1091
source /e2e/lib/common.sh
# Generated by setup.sh from values created in the service containers.
# shellcheck disable=SC1091
source "$E2E_CONFIG_DIR/service-secrets.env"

export E2E_AMNESIA_ACTIVATION
export E2E_AMNESIA_GATEWAY_PUBLIC
export E2E_HEADSCALE_AUTH_KEY
export E2E_WIREGUARD_TAILSCALE_PRIVATE
: "${E2E_AMNESIA_IP:?}"
: "${E2E_AMNESIA_INTERNET_IP:?}"
: "${E2E_PUBLIC_IP:?}"
: "${E2E_EXAMPLE_IP:?}"

export ALMAGEST_E2E_TMP_FILE_STORAGE=0
export ALMAGEST_E2E_FILE_STORAGE="/root/almagest-e2e-store/$E2E_CASE"

capture_pid=""
outer_splitter_name="AutoTunSplitter VPN"

main_ip="$(ip -4 route get "$E2E_AMNESIA_IP" | awk '{for (i=1; i<=NF; i++) if ($i == "src") {print $(i+1); exit}}')"
[[ -n "$main_ip" ]] || fail "main container has no Docker address"
direct_source="$(ip -4 route get "$E2E_PUBLIC_IP" | awk '{for (i=1; i<=NF; i++) if ($i == "src") {print $(i+1); exit}}')"
[[ -n "$direct_source" ]] || fail "main container has no direct internet source address"

direct_router_rules=$'ADDR_S intercept-hosts.stack.test\nADDR_S intercept-hosts.stack.test.\nOR\nADDR_S intercept-dns.stack.test\nOR\nADDR_S intercept-dns.stack.test.\nOR\nDROP\n\nTRUE\nSLOT 1'
amnesia_router_rules=$'ADDR_S intercept-hosts.stack.test\nADDR_S intercept-hosts.stack.test.\nOR\nADDR_S intercept-dns.stack.test\nOR\nADDR_S intercept-dns.stack.test.\nOR\nPORT 443\nAND\nSLOT 1\n\nADDR_S intercept-hosts.stack.test\nADDR_S intercept-hosts.stack.test.\nOR\nADDR_S intercept-dns.stack.test\nOR\nADDR_S intercept-dns.stack.test.\nOR\nPORT 80\nAND\nSLOT 2\n\nTRUE\nSLOT 3'
tun_filter_rules="ADDR_S $E2E_EXAMPLE_IP"$'\nADDR_S intercept-dns.stack.test\nOR\nADDR_S intercept-dns.stack.test.\nOR\nDROP\n\nRULE cmd blocked-fetch\nRULE comm blocked-fetch\nOR\nDROP\n\nPORT 53\nSLOT 2\n\nTRUE\nSLOT 1'
tun_open_rules=$'PORT 53\nSLOT 2\n\nTRUE\nSLOT 1'

cleanup() {
	trap - EXIT
	if [[ -n "$capture_pid" ]]; then
		kill "$capture_pid" 2>/dev/null || true
		wait "$capture_pid" 2>/dev/null || true
	fi
	stop_daemon
	if [[ -x "$E2E_RUNTIME/cleanup-system.sh" ]]; then
		"$E2E_RUNTIME/cleanup-system.sh"
	fi
}
trap cleanup EXIT

tcpdump -l -nn -tttt -i any \
	'udp and (port 41641 or port 41642 or port 51820 or port 51821)' \
	>"$E2E_RUNTIME/tailscale-packets.log" 2>&1 &
capture_pid="$!"

menu_field() {
	local node="$1"
	local block="$2"
	local field="$3"
	cli graph menu --name "$node" | jq -er \
		--arg block "$block" --arg field "$field" '
		.blocks[] | select(.id == $block)
		| .items[] | select(.id == $field)
		| (.value // .text // "")
	'
}

http_client_has() {
	local node="$1"
	local text="$2"
	[[ "$(menu_field "$node" result status)" == "Status: 200 OK" \
		&& -z "$(menu_field "$node" result error)" \
		&& "$(menu_field "$node" result response)" == *"$text"* ]]
}

send_http_client() {
	local node="$1"
	local text="$2"
	cli graph click-menu-button --name "$node" --block request --button send >/dev/null
	if retry "$ALMAGEST_E2E_TIMEOUT" "$node response containing $text" \
		http_client_has "$node" "$text"; then
		return 0
	fi
	cli graph menu --name "$node" >&2 || true
	if [[ "$node" == "HttpClient Tailnet" ]]; then
		cli graph menu --name "TailscaleCtrl" | jq '{status: [.blocks[] | select(.id == "status") | .items[] | select(.id == "state" or .id == "localEndpoints" or .id == "peers" or .id == "error") | {id, value}]}' >&2 || true
		cli graph menu --name "WireGuard Tailscale" | jq '{status: [.blocks[] | select(.id == "status") | .items[] | select(.id == "state" or .id == "connectedPeers" or .id == "rxBytes" or .id == "txBytes" or .id == "latestHandshake" or .id == "error") | {id, value}]}' >&2 || true
	fi
	fail "$node did not return the expected response"
}

http_client_probe() {
	local node="$1"
	local text="$2"
	cli graph click-menu-button --name "$node" --block request --button send >/dev/null
	retry 18 "$node probe response containing $text" http_client_has "$node" "$text"
}

dns_query_noerror() {
	local node="$1"
	[[ "$(menu_field "$node" result status)" == "Status: NOERROR" \
		&& -z "$(menu_field "$node" result error)" \
		&& -n "$(menu_field "$node" result response)" ]]
}

send_dns_query() {
	local node="$1"
	cli graph click-menu-button --name "$node" --block request --button send >/dev/null
	retry "$ALMAGEST_E2E_TIMEOUT" "$node NOERROR result" dns_query_noerror "$node" \
		|| fail "$node did not complete with NOERROR"
}

apply_rules() {
	local node="$1"
	local rules="$2"
	jq -n --arg rules "$rules" '{"config":{"rules":$rules}}' \
		| cli graph apply-menu --name "$node" >/dev/null
}

curl_direct_origin() {
	local program="$1"
	local destination="$2"
	local path="$3"
	local output="$4"
	"$program" --fail --silent --show-error --noproxy '*' \
		--connect-timeout 2 --max-time 8 \
		"http://$destination$path" --output "$output"
}

curl_excluded_origin_has_source() {
	local destination="$1"
	local path="$2"
	local output="$3"
	local source="$4"

	E2E_SOCKET_MARK_TIMEOUT="$ALMAGEST_E2E_TIMEOUT" \
		direct-fetch /e2e/lib/marked-curl.py \
		--fail --silent --show-error --noproxy '*' \
		--connect-timeout 2 --max-time 8 \
		"http://$destination$path" --output "$output" \
		&& grep -F -- "source=$source" "$output" >/dev/null
}

curl_socks() {
	local mode="$1"
	local port="$2"
	local url="$3"
	local output="$4"
	shift 4
	curl --fail --silent --show-error \
		"--$mode" "127.0.0.1:$port" \
		--connect-timeout 2 --max-time 8 \
		"$@" "$url" --output "$output"
}

request_fails() {
	local label="$1"
	shift
	if "$@" >"$E2E_RUNTIME/$label.stdout" 2>"$E2E_RUNTIME/$label.stderr"; then
		return 1
	fi
	return 0
}

marked_request_fails() {
	local label="$1"
	shift
	local status

	if E2E_SOCKET_MARK_TIMEOUT="$ALMAGEST_E2E_TIMEOUT" \
		direct-fetch /e2e/lib/marked-curl.py "$@" \
		>"$E2E_RUNTIME/$label.stdout" 2>"$E2E_RUNTIME/$label.stderr"; then
		return 1
	else
		status="$?"
	fi
	if ((status == 125)); then
		cat "$E2E_RUNTIME/$label.stderr" >&2
		return 1
	fi
	return 0
}

assert_contains() {
	local file="$1"
	local text="$2"
	if ! grep -F -- "$text" "$file" >/dev/null; then
		echo "$(basename "$file") content:" >&2
		sed -n '1,40p' "$file" >&2 || true
		fail "$(basename "$file") does not contain: $text"
	fi
}

node_label_matches() {
	local name="$1"
	local expression="$2"
	local label
	label="$(cli graph node --name "$name" | jq -er '.snapshot.label')" || return 1
	[[ "$label" =~ $expression ]]
}

graph_operational_once() {
	local spec name expression
	local specs=(
		'OutNetwork direct|^out$'
		'Amnesia VPN|^up$'
		'VTun Amnesia|^amnesia-transport$'
		'TunJoiner VPN|^joined default \+ 1 secondary$'
		'DnsClient VPN|^1 DNS server$'
		'DnsCache vt|^caching DNS$'
		'DnsQuery public|^(ready|NOERROR)$'
		'DnsQuery intercepted|^(ready|NOERROR)$'
		'TailscaleCtrl|^up$'
		'WireGuard Tailscale|^up$'
		'DnsQuery tailnet|^(ready|NOERROR)$'
		"$outer_splitter_name|^splitting$"
		'TunJoiner applications|^joined default \+ 1 secondary$'
		'VTun applications|^application-stack$'
		'HttpClient Tailnet|^(ready|200 OK)$'
		'HttpClient A|^(ready|200 OK)$'
		'HttpClient B|^(ready|200 OK)$'
		'Proxy direct|^127\.0\.0\.1:1081$'
		'NetworkRouter direct|^router$'
		'Proxy Amnesia only|^127\.0\.0\.1:1082$'
		'NetworkRouter Amnesia only|^router$'
		'TlsMitm intercepted|^intercepting TLS$'
		'TlsTerminator intercepted|^terminating TLS$'
		'MockNetwork intercepted|^loopback$'
		'HttpServer intercepted|^127\.0\.0\.1:80$'
		'Tun2Dns default|^adapting DNS$'
		'TunSplitter lH|^splitting$'
		'DefaultTun|^ready$'
	)
	for spec in "${specs[@]}"; do
		name="${spec%%|*}"
		expression="${spec#*|}"
		node_label_matches "$name" "$expression" || return 1
	done
}

wait_graph_operational_stable() {
	retry "$ALMAGEST_E2E_TIMEOUT" "all graph nodes operational" graph_operational_once \
		|| {
			while IFS= read -r name; do
				printf '%s\t%s\n' "$name" \
					"$(cli graph node --name "$name" | jq -er '.snapshot.label' || true)" >&2
			done < <(cli graph map | jq -r '.nodes | keys[]')
			cli graph menu --name "TailscaleCtrl" >&2 || true
			cli graph map >&2 || true
			fail "not all graph nodes became operational"
		}
	local deadline=$((SECONDS + 5))
	while ((SECONDS <= deadline)); do
		graph_operational_once || fail "a graph node left its operational state during the stability window"
		sleep 0.25
	done
}

tailscale_peer_direct() {
	local peers
	peers="$(menu_field "TailscaleCtrl" status peers)" || return 1
	local endpoints
	endpoints="$(menu_field "TailscaleCtrl" status localEndpoints)" || return 1
	[[ "$peers" == *"path=direct-udp"* \
		&& "$endpoints" == *"10.205.10.1:"* ]]
}

cache_contains_name() {
	local name="$1"
	cli dns keys --cache default | jq -e --arg name "$name" \
		'.exists and any(.keys[]?; .key | contains($name))' >/dev/null
}

# Check the initial Docker topology before Almagest changes this container's
# routes. The public fixture is directly reachable. The Headscale controller,
# Amnesia tunnel address, and tailnet service are not directly reachable.
retry 20 "direct public fixture before daemon" \
	curl_direct_origin curl "$E2E_PUBLIC_IP" /before-daemon "$E2E_RUNTIME/before-daemon.txt" \
	|| fail "public fixture was not directly reachable before daemon startup"
assert_contains "$E2E_RUNTIME/before-daemon.txt" "source=$direct_source"
request_fails headscale-direct-before \
	curl -kfsS --connect-timeout 1 --max-time 3 "https://$E2E_HEADSCALE_IP:18090/health" \
	|| fail "Headscale was directly reachable from the main container"
request_fails amnesia-tunnel-before \
	curl -fsS --connect-timeout 1 --max-time 3 http://10.205.20.1/ \
	|| fail "Amnesia tunnel address was reachable before the tunnel started"
request_fails tailnet-before \
	curl -fsS --connect-timeout 1 --max-time 3 http://100.64.0.1:18080/ \
	|| fail "tailnet service was reachable before the nested tunnels started"

start_daemon
trap cleanup EXIT

wait_node_label "$(node_id_by_name "Amnesia VPN")" up \
	|| fail "managed Amnesia node did not import the local gateway profile"
client_key="$(sed -n 's/.*local_public_key=\([^ ]*\).*/\1/p' "$E2E_DAEMON_LOG" | tail -1)"
[[ -n "$client_key" && "$client_key" != none ]] \
	|| fail "managed Amnesia client key was not logged"
printf '%s %s\n' "$main_ip" "$client_key" >/stack-shared/amnesia-client-peer
retry 30 "Amnesia server peer installation" test -f /stack-shared/amnesia-peer-ready \
	|| fail "Amnesia service did not install the managed client peer"

wait_graph_operational_stable
wait_log_contains "almagest/LocalProxy" "socks listening on 127.0.0.1:1081" \
	|| fail "direct SOCKS proxy did not listen"
wait_log_contains "almagest/LocalProxy" "socks listening on 127.0.0.1:1082" \
	|| fail "Amnesia SOCKS proxy did not listen"
retry "$ALMAGEST_E2E_TIMEOUT" "direct Tailscale peer path through Amnesia" tailscale_peer_direct \
	|| fail "nested Tailscale did not select direct UDP to the local peer"
retry "$ALMAGEST_E2E_TIMEOUT" "operational Tailscale data plane through Amnesia" \
	http_client_probe "HttpClient Tailnet" "tailnet HttpServer SO response" \
	|| fail "nested Tailscale data plane did not become operational"

# All graph DNS probes must complete successfully. These populate the same
# persistent DNS cache that the routers and the TUN splitter use for reverse
# destination matching.
send_dns_query "DnsQuery public"
send_dns_query "DnsQuery intercepted"
send_dns_query "DnsQuery tailnet"
retry 20 "public DNS cache entry" cache_contains_name public.stack.test \
	|| fail "public DNS query is not visible in cache storage"
retry 20 "intercept DNS cache entry" cache_contains_name intercept-dns.stack.test \
	|| fail "intercept DNS query is not visible in cache storage"

# Direct and managed HttpClient nodes use different egress paths. The third
# client enters the application VTun, selects the tailnet slot, and reaches the
# peer service while both Tailscale control and packets use Amnesia transport.
send_http_client "HttpClient A" "destination=$E2E_PUBLIC_IP source=$direct_source"
send_http_client "HttpClient B" "destination=$E2E_PUBLIC_IP source=$E2E_AMNESIA_INTERNET_IP"
http_client_has "HttpClient Tailnet" "tailnet HttpServer SO response" \
	|| fail "tailnet readiness response was lost before traffic checks"

cli tls builtin-ca | jq -er '.cert.pem' >"$E2E_RUNTIME/builtin-ca.pem"

# Baseline SOCKS behavior with all destination filters enabled.
retry 20 "direct SOCKS public access" \
	curl_socks socks5-hostname 1081 "http://$E2E_PUBLIC_IP/socks-direct" \
		"$E2E_RUNTIME/socks-direct.txt" \
	|| fail "direct SOCKS proxy could not reach the public fixture"
assert_contains "$E2E_RUNTIME/socks-direct.txt" "source=$direct_source"

for domain in intercept-hosts.stack.test intercept-dns.stack.test; do
	request_fails "direct-block-$domain" \
		curl_socks socks5-hostname 1081 "http://$domain/direct-block" \
		"$E2E_RUNTIME/direct-block-$domain.txt" \
		|| fail "direct SOCKS router did not block $domain"
done

retry 20 "Amnesia SOCKS public access" \
	curl_socks socks5-hostname 1082 "http://$E2E_PUBLIC_IP/socks-amnesia" \
		"$E2E_RUNTIME/socks-amnesia.txt" \
	|| fail "Amnesia SOCKS proxy could not reach the public fixture"
assert_contains "$E2E_RUNTIME/socks-amnesia.txt" "source=$E2E_AMNESIA_INTERNET_IP"

domain=intercept-dns.stack.test
retry 20 "HTTP interception for $domain" \
	curl_socks socks5-hostname 1082 "http://$domain/http-intercept" \
	"$E2E_RUNTIME/http-intercept-$domain.txt" \
	|| fail "Amnesia SOCKS router did not intercept HTTP for $domain"
assert_contains "$E2E_RUNTIME/http-intercept-$domain.txt" "intercepted stack target"

retry 20 "HTTPS interception for $domain" \
	curl_socks socks5-hostname 1082 "https://$domain/https-intercept" \
	"$E2E_RUNTIME/https-intercept-$domain.txt" \
	--http1.1 --cacert "$E2E_RUNTIME/builtin-ca.pem" \
	|| fail "Amnesia SOCKS router did not intercept HTTPS for $domain"
assert_contains "$E2E_RUNTIME/https-intercept-$domain.txt" "intercepted stack target"

# Local SOCKS resolution converts the DNS-served name to an IP. Reverse cache
# lookup must still select the interception slots for HTTP and HTTPS.
retry 20 "pre-resolved HTTP interception" \
	curl_socks socks5 1082 http://intercept-dns.stack.test/pre-resolved-http \
		"$E2E_RUNTIME/pre-resolved-http.txt" \
	|| fail "pre-resolved SOCKS HTTP request was not intercepted"
assert_contains "$E2E_RUNTIME/pre-resolved-http.txt" "intercepted stack target"
retry 20 "pre-resolved HTTPS interception" \
	curl_socks socks5 1082 https://intercept-dns.stack.test/pre-resolved-https \
		"$E2E_RUNTIME/pre-resolved-https.txt" \
		--http1.1 --cacert "$E2E_RUNTIME/builtin-ca.pem" \
	|| fail "pre-resolved SOCKS HTTPS request was not intercepted"
assert_contains "$E2E_RUNTIME/pre-resolved-https.txt" "intercepted stack target"

# DefaultTun sends ordinary traffic through Amnesia. The renamed browser-like
# command is excluded and stays direct. DNS packets sent to an unrelated
# address are captured by Tun2Dns. Destination and application rules drop the
# selected targets, while the nested tailnet remains reachable.
retry 20 "DefaultTun public access through Amnesia" \
	curl_direct_origin curl "$E2E_PUBLIC_IP" /default-tun "$E2E_RUNTIME/default-tun.txt" \
	|| fail "DefaultTun traffic could not reach the public fixture"
assert_contains "$E2E_RUNTIME/default-tun.txt" "source=$E2E_AMNESIA_INTERNET_IP"
retry 20 "DefaultTun excluded application direct access" \
	curl_excluded_origin_has_source "$E2E_PUBLIC_IP" /excluded \
		"$E2E_RUNTIME/excluded.txt" "$direct_source" \
	|| fail "excluded application did not retain direct access"
marked_request_fails headscale-excluded-direct \
	-kfsS --connect-timeout 1 --max-time 3 "https://$E2E_HEADSCALE_IP:18090/health" \
	|| fail "excluded direct application bypassed the Headscale source guard"

dig +time=2 +tries=2 @198.51.100.53 intercept-dns.stack.test A \
	>"$E2E_RUNTIME/intercepted-dns.txt"
grep -F 'status: NOERROR' "$E2E_RUNTIME/intercepted-dns.txt" >/dev/null \
	|| fail "DefaultTun did not intercept the UDP DNS query"
grep -F "$E2E_EXAMPLE_IP" "$E2E_RUNTIME/intercepted-dns.txt" >/dev/null \
	|| fail "intercepted UDP DNS response did not contain the fixture address"

request_fails tun-block-hosts \
	curl_direct_origin curl intercept-hosts.stack.test /blocked-hosts \
		"$E2E_RUNTIME/tun-block-hosts.txt" \
	|| fail "TunSplitter did not block the /etc/hosts destination"
request_fails tun-block-dns \
	curl_direct_origin curl intercept-dns.stack.test /blocked-dns \
		"$E2E_RUNTIME/tun-block-dns.txt" \
	|| fail "TunSplitter did not block the DNS/cache destination"
request_fails tun-block-app \
	curl_direct_origin blocked-fetch "$E2E_PUBLIC_IP" /blocked-app \
		"$E2E_RUNTIME/tun-block-app.txt" \
	|| fail "TunSplitter did not block the selected application"
retry 30 "tailnet service from DefaultTun" \
	curl_direct_origin curl 100.64.0.1:18080 /default-tun-tailnet \
		"$E2E_RUNTIME/default-tun-tailnet.txt" \
	|| fail "DefaultTun traffic could not reach HttpServer SO in the tailnet"
assert_contains "$E2E_RUNTIME/default-tun-tailnet.txt" "tailnet HttpServer SO response"

# Disable and restore each destination/application filter independently. The
# TunSplitter checks exercise both /etc/hosts and the container DNS daemon.
apply_rules "NetworkRouter direct" $'TRUE\nSLOT 1'
domain=intercept-dns.stack.test
retry 20 "open direct router access to $domain" \
	curl_socks socks5-hostname 1081 "http://$domain/direct-open" \
	"$E2E_RUNTIME/direct-open-$domain.txt" \
	|| fail "disabled direct router filter still blocked $domain"
assert_contains "$E2E_RUNTIME/direct-open-$domain.txt" "source=$direct_source"
apply_rules "NetworkRouter direct" "$direct_router_rules"
request_fails direct-restored-block \
	curl_socks socks5-hostname 1081 \
		http://intercept-dns.stack.test/direct-restored-block \
		"$E2E_RUNTIME/direct-restored-block.txt" \
	|| fail "restored direct router filter did not block the DNS domain"

apply_rules "NetworkRouter Amnesia only" $'TRUE\nSLOT 3'
domain=intercept-dns.stack.test
retry 20 "open Amnesia router access to $domain" \
	curl_socks socks5-hostname 1082 "http://$domain/amnesia-open" \
	"$E2E_RUNTIME/amnesia-open-$domain.txt" \
	|| fail "disabled Amnesia router interception still captured $domain"
assert_contains "$E2E_RUNTIME/amnesia-open-$domain.txt" "source=$E2E_AMNESIA_INTERNET_IP"
apply_rules "NetworkRouter Amnesia only" "$amnesia_router_rules"
retry 20 "restored Amnesia interception" \
	curl_socks socks5-hostname 1082 \
		http://intercept-dns.stack.test/amnesia-restored \
		"$E2E_RUNTIME/amnesia-restored.txt" \
	|| fail "restored Amnesia router filter did not intercept the DNS domain"
assert_contains "$E2E_RUNTIME/amnesia-restored.txt" "intercepted stack target"

apply_rules "TunSplitter lH" "$tun_open_rules"
for domain in intercept-hosts.stack.test intercept-dns.stack.test; do
	retry 20 "open TunSplitter access to $domain" \
		curl_direct_origin curl "$domain" /tun-open \
		"$E2E_RUNTIME/tun-open-$domain.txt" \
		|| fail "disabled TunSplitter destination filter still blocked $domain"
	assert_contains "$E2E_RUNTIME/tun-open-$domain.txt" "source=$E2E_AMNESIA_INTERNET_IP"
done
retry 20 "open TunSplitter application access" \
	curl_direct_origin blocked-fetch "$E2E_PUBLIC_IP" /app-open \
		"$E2E_RUNTIME/app-open.txt" \
	|| fail "disabled TunSplitter application filter still blocked blocked-fetch"
assert_contains "$E2E_RUNTIME/app-open.txt" "source=$E2E_AMNESIA_INTERNET_IP"
apply_rules "TunSplitter lH" "$tun_filter_rules"
request_fails tun-restored-destination \
	curl_direct_origin curl intercept-dns.stack.test /tun-restored \
		"$E2E_RUNTIME/tun-restored.txt" \
	|| fail "restored TunSplitter destination filter did not block the DNS domain"
request_fails tun-restored-app \
	curl_direct_origin blocked-fetch "$E2E_PUBLIC_IP" /app-restored \
		"$E2E_RUNTIME/app-restored.txt" \
	|| fail "restored TunSplitter application filter did not block blocked-fetch"

retry 20 "DNS cache remains visible after traffic checks" \
	cache_contains_name intercept-dns.stack.test \
	|| fail "DNS cache entry disappeared after the routing matrix"
wait_graph_operational_stable

# Restart with the original manual splitter graph. Check both routing slots:
# normal DefaultTun traffic must use the VPN, and tailnet traffic must use the
# WireGuard slot. This focused pass verifies that AutoTunSplitter is a drop-in
# replacement without running the unrelated filter matrix a second time.
stop_daemon
cp "$E2E_RUNTIME/alm-manual-splitter.hujson" "$E2E_CONFIG_DIR/alm.hujson"
outer_splitter_name="TunSplitter VPN"
start_daemon
trap cleanup EXIT
# A managed Amnesia runtime creates a new client key after restart. Give the
# replacement key to the fixture before Tailscale tries to use the VPN again.
wait_node_label "$(node_id_by_name "Amnesia VPN")" up \
	|| fail "restarted managed Amnesia node did not become ready"
client_key="$(sed -n 's/.*local_public_key=\([^ ]*\).*/\1/p' "$E2E_DAEMON_LOG" | tail -1)"
[[ -n "$client_key" && "$client_key" != none ]] \
	|| fail "restarted managed Amnesia client key was not logged"
printf '%s %s\n' "$main_ip" "$client_key" >/stack-shared/amnesia-client-peer
wait_graph_operational_stable
retry "$ALMAGEST_E2E_TIMEOUT" "manual splitter default slot through Amnesia" \
	curl_direct_origin curl "$E2E_PUBLIC_IP" /manual-splitter \
		"$E2E_RUNTIME/manual-splitter-default.txt" \
	|| fail "manual TunSplitter default slot could not reach the public fixture"
assert_contains "$E2E_RUNTIME/manual-splitter-default.txt" \
	"source=$E2E_AMNESIA_INTERNET_IP"
send_http_client "HttpClient Tailnet" "tailnet HttpServer SO response"

log "case passed with automatic and manual outer splitters"
